#!/usr/bin/env bash
#
# install_strongswan.sh - turn this Ubuntu 22.04 EC2 into the "on-prem" VPN router.
#
# Run ON the on-prem EC2, from the copied onprem/ folder:
#     sudo ./install_strongswan.sh
#
# Needs these files next to the script (generated by `terraform apply`):
#     lab.env        non-secret values (tunnel IPs, routing mode, ...)
#     swanctl.conf   tunnel config with the pre-shared keys
# BGP mode additionally needs frr.conf.template (shipped in this folder).
#
# Safe to re-run (idempotent). Re-run it after any `terraform apply` that
# changes the VPN connection (for example static -> bgp).

set -euo pipefail

SRC_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

[[ $EUID -eq 0 ]] || { echo "ERROR: run with sudo." >&2; exit 1; }

for f in lab.env swanctl.conf; do
  [[ -f "$SRC_DIR/$f" ]] || {
    echo "ERROR: $SRC_DIR/$f not found. Run 'terraform apply' on your laptop, then scp the onprem/ folder here." >&2
    exit 1
  }
done

# shellcheck disable=SC1091
set -a; source "$SRC_DIR/lab.env"; set +a

echo "==> Routing mode: $ROUTING_MODE"

# -----------------------------------------------------------------------------
# 1. Packages
# -----------------------------------------------------------------------------
echo "==> Installing packages"
export DEBIAN_FRONTEND=noninteractive
apt-get update -y
# charon-systemd + strongswan-swanctl = modern swanctl stack (NOT the old ipsec.conf "starter").
apt-get install -y charon-systemd strongswan-swanctl libstrongswan-standard-plugins \
  traceroute mtr-tiny tcpdump iputils-ping net-tools gettext-base
if [[ "$ROUTING_MODE" == "bgp" ]]; then
  apt-get install -y frr
fi

# -----------------------------------------------------------------------------
# 2. Kernel settings: IP forwarding + relaxed reverse-path filtering
# -----------------------------------------------------------------------------
echo "==> Enabling IP forwarding"
cat > /etc/sysctl.d/99-hybrid-lab.conf <<'EOF'
# This box routes packets between the VPC and the VPN tunnels.
net.ipv4.ip_forward = 1

# Replies may come back through the OTHER tunnel than the one the request used.
# Strict reverse-path filtering would drop those packets, so turn it off.
net.ipv4.conf.all.rp_filter = 0
net.ipv4.conf.default.rp_filter = 0

# A router should not send/accept ICMP redirects.
net.ipv4.conf.all.send_redirects = 0
net.ipv4.conf.all.accept_redirects = 0
EOF
sysctl --system >/dev/null
echo "    ip_forward = $(sysctl -n net.ipv4.ip_forward)"

# -----------------------------------------------------------------------------
# 3. Source/destination check reminder (this is an AWS setting, not a Linux one)
# -----------------------------------------------------------------------------
echo "==> NOTE: the EC2 'source/destination check' must be DISABLED."
echo "    Terraform sets source_dest_check = false. Verify from your laptop:"
echo "    aws ec2 describe-instance-attribute --instance-id <id> --attribute sourceDestCheck"

# -----------------------------------------------------------------------------
# 4. strongSwan config + helper scripts
# -----------------------------------------------------------------------------
echo "==> Installing strongSwan config"
install -m 600 "$SRC_DIR/swanctl.conf" /etc/swanctl/swanctl.conf
install -m 644 "$SRC_DIR/lab.env" /etc/hybrid-lab.env

# --- xfrm interface helper: one virtual interface per tunnel -----------------
cat > /usr/local/sbin/hybrid-lab-vti.sh <<'EOF'
#!/usr/bin/env bash
# Creates / removes xfrm-aws1 and xfrm-aws2. if_id ties each interface to one IPsec tunnel.
set -euo pipefail
source /etc/hybrid-lab.env
UNDERLAY_IF="$(ip -4 route show default | awk '{print $5; exit}')"

up() {
  for n in 1 2; do
    ifname="xfrm-aws${n}"
    id_var="T${n}_IF_ID"
    cgw_var="T${n}_CGW_INSIDE"
    ip link show "$ifname" &>/dev/null || ip link add "$ifname" type xfrm dev "$UNDERLAY_IF" if_id "${!id_var}"
    ip addr replace "${!cgw_var}/30" dev "$ifname"
    ip link set "$ifname" mtu 1400 up
  done
}

down() {
  for n in 1 2; do ip link del "xfrm-aws${n}" 2>/dev/null || true; done
}

case "${1:-}" in
  up) up ;;
  down) down ;;
  *) echo "usage: $0 up|down" >&2; exit 1 ;;
esac
EOF
chmod 755 /usr/local/sbin/hybrid-lab-vti.sh

cat > /etc/systemd/system/hybrid-lab-vti.service <<'EOF'
[Unit]
Description=Hybrid lab xfrm interfaces for AWS tunnels
After=network-online.target
Wants=network-online.target
Before=strongswan.service

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/usr/local/sbin/hybrid-lab-vti.sh up
ExecStop=/usr/local/sbin/hybrid-lab-vti.sh down

[Install]
WantedBy=multi-user.target
EOF

# --- static-mode route manager (failover) ------------------------------------
cat > /usr/local/sbin/hybrid-lab-monitor.sh <<'EOF'
#!/usr/bin/env bash
# STATIC mode only. xfrm interfaces never go "down" when a tunnel dies, so plain static
# routes would keep sending traffic into a dead tunnel. This loop pings the AWS side of
# each tunnel and adds/removes that tunnel's routes. Tunnel 1 = metric 100 (preferred),
# tunnel 2 = metric 200 (backup).
source /etc/hybrid-lab.env
declare -A METRIC=([1]=100 [2]=200)
declare -A STATE=([1]=unknown [2]=unknown)

while true; do
  for n in 1 2; do
    ifname="xfrm-aws${n}"
    peer_var="T${n}_AWS_INSIDE"
    if ping -I "$ifname" -c1 -W1 "${!peer_var}" &>/dev/null; then new=up; else new=down; fi

    for prefix in $AWS_PREFIXES; do
      if [[ $new == up ]]; then
        # "src" makes packets leave with our VPC IP, not the 169.254 tunnel address.
        ip route replace "$prefix" dev "$ifname" metric "${METRIC[$n]}" src "$ONPREM_PRIVATE_IP"
      else
        ip route del "$prefix" dev "$ifname" metric "${METRIC[$n]}" 2>/dev/null || true
      fi
    done

    if [[ ${STATE[$n]} != "$new" ]]; then
      echo "tunnel${n}: ${STATE[$n]} -> ${new}"
      STATE[$n]=$new
    fi
  done
  sleep 5
done
EOF
chmod 755 /usr/local/sbin/hybrid-lab-monitor.sh

cat > /etc/systemd/system/hybrid-lab-monitor.service <<'EOF'
[Unit]
Description=Hybrid lab static route failover monitor
After=strongswan.service

[Service]
ExecStart=/usr/local/sbin/hybrid-lab-monitor.sh
Restart=always

[Install]
WantedBy=multi-user.target
EOF

systemctl daemon-reload

# -----------------------------------------------------------------------------
# 5. Start everything
# -----------------------------------------------------------------------------
echo "==> Starting tunnels"
systemctl stop hybrid-lab-monitor.service 2>/dev/null || true
systemctl enable hybrid-lab-vti.service >/dev/null 2>&1
systemctl restart hybrid-lab-vti.service
systemctl enable strongswan >/dev/null 2>&1
systemctl restart strongswan
sleep 3
swanctl --load-all

if [[ "$ROUTING_MODE" == "static" ]]; then
  echo "==> Static mode: starting route failover monitor"
  systemctl enable --now hybrid-lab-monitor.service >/dev/null 2>&1
else
  echo "==> BGP mode: configuring FRR"
  [[ -f "$SRC_DIR/frr.conf.template" ]] || { echo "ERROR: frr.conf.template missing" >&2; exit 1; }
  # Static-mode leftovers must go, otherwise they shadow BGP routes.
  systemctl disable --now hybrid-lab-monitor.service >/dev/null 2>&1 || true
  for p in $AWS_PREFIXES; do
    ip route del "$p" dev xfrm-aws1 2>/dev/null || true
    ip route del "$p" dev xfrm-aws2 2>/dev/null || true
  done
  sed -i 's/^bgpd=no/bgpd=yes/' /etc/frr/daemons
  envsubst '$ONPREM_PRIVATE_IP $ONPREM_ASN $AWS_ASN $T1_AWS_INSIDE $T2_AWS_INSIDE $ONPREM_SUBNET_CIDR $ONPREM_VPC_CIDR' \
    < "$SRC_DIR/frr.conf.template" > /etc/frr/frr.conf
  chown frr:frr /etc/frr/frr.conf
  chmod 640 /etc/frr/frr.conf
  systemctl enable frr >/dev/null 2>&1
  systemctl restart frr
fi

# -----------------------------------------------------------------------------
# 6. Quick status
# -----------------------------------------------------------------------------
sleep 8
echo
echo "==> IKE/IPsec security associations:"
swanctl --list-sas || true
echo
echo "==> Interfaces:"
ip -br addr show | grep xfrm || true
echo
echo "==> Routes to AWS:"
ip route | grep -E "xfrm-aws" || echo "(none yet - static: wait ~10s for the monitor; bgp: wait ~30s for sessions)"
echo
echo "Done. Ping test:  ping -c3 <private IP of a test EC2>"
